    # =================================================================
    #  HASKELL (haskell_) - 8 rules
    # =================================================================

    {
        "id": "haskell_unsafePerformIO",
        "pattern": r"unsafePerformIO",
        "message": "unsafePerformIO breaks referential transparency. Use IO monad properly.",
        "severity": Severity.BLOCK,
            "suggestion": (
                "unsafePerformIO breaks referential transparency — the foundation of Haskell's type safety. A pure function that secretly does IO can: file I/O, network calls, mutable state. Use IO monad explicitly."
            ),
        "file_types": [".hs", ".lhs"],
    },
    {
        "id": "haskell_head_empty_list",
        "pattern": r"(?:^|[^-])\bhead\s+(?!\$)",
        "message": "head on potentially empty list throws exception. Use pattern matching or headMay.",
        "severity": Severity.WARN,
            "suggestion": (
                "head [] throws 'Prelude.head: empty list' — a runtime crash with no useful information. Use: case xs of (x:_) -> x; [] -> defaultValue. Or: headMay from safe package."
            ),
        "file_types": [".hs", ".lhs"],
    },
    {
        "id": "haskell_incomplete_pattern",
        "pattern": r"(?:case\s+\w+\s+of(?:(?!\n\s*_)[\s\S]){0,200})\n\s*\n",
        "message": "Case expression may have incomplete patterns. Add a wildcard (_) or cover all constructors.",
        "severity": Severity.WARN,
            "suggestion": (
                "Non-exhaustive patterns: a runtime crash when the missing case is hit. GHC warns with -Wall. Add all constructors or a wildcard: _ -> error 'Unexpected case: report this bug'."
            ),
        "file_types": [".hs", ".lhs"],
    },
    {
        "id": "haskell_unsafe_coerce",
        "pattern": r"unsafeCoerce",
        "message": "unsafeCoerce bypasses the type system. Use proper type conversions.",
        "severity": Severity.BLOCK,
            "suggestion": (
                "unsafeCoerce :: a -> b bypasses the type system entirely. If a and b have different representations: undefined behavior, segfaults, data corruption. Use proper type conversions."
            ),
        "file_types": [".hs", ".lhs"],
    },
    {
        "id": "haskell_fromJust",
        "pattern": r"fromJust(?!\s*\.\s*lookup)",
        "message": "fromJust crashes on Nothing. Use maybe, fromMaybe, or pattern matching.",
        "severity": Severity.WARN,
            "suggestion": (
                "fromJust Nothing = error 'Maybe.fromJust: Nothing' — a runtime crash. Use: fromMaybe defaultValue maybeVal, or pattern match: case m of Just x -> f x; Nothing -> g."
            ),
        "file_types": [".hs", ".lhs"],
    },
    {
        "id": "haskell_read_no_safe",
        "pattern": r"\bread\s+['\"]",
        "message": "read throws on invalid input. Use readMaybe or readEither for safe parsing.",
        "severity": Severity.WARN,
            "suggestion": (
                "read 'not_a_number' :: Int throws an exception. Use: readMaybe 'not_a_number' :: Maybe Int returns Nothing. Or readEither for an error message."
            ),
        "file_types": [".hs", ".lhs"],
    },
    {
        "id": "haskell_error_call",
        "pattern": r"\berror\s+['\"]",
        "message": "error throws an unrecoverable exception. Use Either, Maybe, or MonadError for recoverable errors.",
        "severity": Severity.WARN,
            "suggestion": (
                "error throws an unrecoverable exception — equivalent to panic. Use: Either ErrorType Result for recoverable errors. MonadError or ExceptT in monadic code."
            ),
        "file_types": [".hs", ".lhs"],
    },
    {
        "id": "haskell_unsafeIOToSTM",
        "pattern": r"unsafeIOToSTM",
        "message": "unsafeIOToSTM can violate STM invariants. Keep IO effects outside STM transactions.",
        "severity": Severity.BLOCK,
            "suggestion": (
                "unsafeIOToSTM violates STM's guarantee that transactions can be safely retried. The IO effect runs on every retry — file writes, network calls, database mutations happen multiple times."
            ),
        "file_types": [".hs", ".lhs"],
    },

    # =================================================================
    #  ERLANG / ELIXIR ADVANCED (erlang_) - 8 rules
